def count_full_weekends_in_range(start_day_num, end_day_num):
    count = 0
    for day in range(start_day_num, end_day_num + 1):
        if day % 7 == 5 and day + 1 <= end_day_num:
            count += 1
    return count

def business_days_needed_for_target(start_day_num, target_day_num, weekend_days):
