def is_balanced_parens(s):
    balance = 0
    for ch in s:
        if ch == '(':
            balance += 1
        elif ch == ')':
            balance -= 1
            if balance < 0:
                return False
        else:
            return False
    return balance == 0

def sum_of_even_divisors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if i % 2 == 0:
                total += i
            if j != i and j % 2 == 0:
                total += j
        i += 1
    return total

