def longest_decreasing_run(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            cur += 1
            best = max(best, cur)
        else:
            cur = 1
    return best

