def vowel_consonant_count(s):
    vowel_set = set('aeiouAEIOU')
    counts = {'vowels': 0, 'consonants': 0}
    for ch in s:
        if ch.isalpha():
            if ch in vowel_set:
                counts['vowels'] += 1
            else:
                counts['consonants'] += 1
    return counts
